package kvhttp

import "core:bytes"
import "core:fmt"
import "core:net"
import "core:strconv"
import "core:strings"

MAX_HEADER_BYTES :: 16 * 1024
MAX_BODY_BYTES :: 1024 * 1024

Request :: struct {
	method: string,
	path:   string,
	// Allocated with the store's allocator so PUT can hand it over without copying.
	body:   []byte,
}

Status :: enum u16 {
	OK                      = 200,
	Created                 = 201,
	No_Content              = 204,
	Bad_Request             = 400,
	Not_Found               = 404,
	Method_Not_Allowed      = 405,
	Request_Timeout         = 408,
	Payload_Too_Large       = 413,
	Header_Fields_Too_Large = 431,
	Internal_Server_Error   = 500,
	Not_Implemented         = 501,
}

status_reason :: proc(s: Status) -> string {
	switch s {
	case .OK:                      return "OK"
	case .Created:                 return "Created"
	case .No_Content:              return "No Content"
	case .Bad_Request:             return "Bad Request"
	case .Not_Found:               return "Not Found"
	case .Method_Not_Allowed:      return "Method Not Allowed"
	case .Request_Timeout:         return "Request Timeout"
	case .Payload_Too_Large:       return "Payload Too Large"
	case .Header_Fields_Too_Large: return "Request Header Fields Too Large"
	case .Internal_Server_Error:   return "Internal Server Error"
	case .Not_Implemented:         return "Not Implemented"
	}
	return "Unknown"
}

Response :: struct {
	status:       Status,
	content_type: string,
	body:         []byte,
	allow:        string,
}

Read_Error :: enum {
	None,
	Closed,       // peer went away or the socket failed; nothing can be sent
	Malformed,    // 400
	Timeout,      // 408
	Too_Large,    // 413
	Header_Large, // 431
	Unsupported,  // 501
	Out_Of_Memory, // 500
}

read_error_status :: proc(e: Read_Error) -> Status {
	#partial switch e {
	case .Malformed:     return .Bad_Request
	case .Timeout:       return .Request_Timeout
	case .Too_Large:     return .Payload_Too_Large
	case .Header_Large:  return .Header_Fields_Too_Large
	case .Unsupported:   return .Not_Implemented
	}
	return .Internal_Server_Error
}

// read_request reads one HTTP/1.1 request from `sock`. The head is parsed out of
// `head_buf`, so `method` and `path` alias it. The body is allocated with
// `body_allocator` and owned by the caller.
read_request :: proc(
	sock: net.TCP_Socket,
	head_buf: []byte,
	body_allocator := context.allocator,
) -> (
	req: Request,
	err: Read_Error,
) {
	filled := 0
	head_end := -1
	for head_end < 0 {
		if filled == len(head_buf) {
			return {}, .Header_Large
		}
		n, recv_err := net.recv_tcp(sock, head_buf[filled:])
		if recv_err != nil {
			return {}, recv_error(recv_err, filled)
		}
		if n == 0 {
			return {}, .Closed if filled == 0 else .Malformed
		}
		// Rescan a few bytes before the new data in case the terminator straddles reads.
		scan_from := max(filled - 3, 0)
		filled += n
		if i := bytes.index(head_buf[scan_from:filled], {'\r', '\n', '\r', '\n'}); i >= 0 {
			head_end = scan_from + i
		}
	}

	head := string(head_buf[:head_end])
	leftover := head_buf[head_end + 4:filled]

	content_length := parse_head(head, &req) or_return
	if content_length > MAX_BODY_BYTES {
		return {}, .Too_Large
	}
	if content_length == 0 {
		return req, .None
	}

	body, alloc_err := make([]byte, content_length, body_allocator)
	if alloc_err != nil {
		return {}, .Out_Of_Memory
	}
	defer if err != .None {
		delete(body, body_allocator)
	}

	got := copy(body, leftover)
	for got < content_length {
		n, recv_err := net.recv_tcp(sock, body[got:])
		if recv_err != nil {
			return {}, recv_error(recv_err, 1)
		}
		if n == 0 {
			return {}, .Closed
		}
		got += n
	}
	req.body = body
	return req, .None
}

@(private = "file")
recv_error :: proc(e: net.TCP_Recv_Error, received: int) -> Read_Error {
	if e == .Timeout && received > 0 {
		return .Timeout
	}
	return .Closed
}

// parse_head parses the request line and headers, filling method and path.
@(private = "file")
parse_head :: proc(head: string, req: ^Request) -> (content_length: int, err: Read_Error) {
	rest := head
	request_line, _ := strings.split_iterator(&rest, "\r\n")

	parts := request_line
	method, _ := strings.split_iterator(&parts, " ")
	target, _ := strings.split_iterator(&parts, " ")
	version := parts
	if method == "" || target == "" || !strings.has_prefix(version, "HTTP/1.") {
		return 0, .Malformed
	}
	if !strings.has_prefix(target, "/") {
		return 0, .Malformed
	}
	// Queries are not part of routing.
	if q := strings.index_byte(target, '?'); q >= 0 {
		target = target[:q]
	}
	req.method = method
	req.path = target

	have_length := false
	for line in strings.split_iterator(&rest, "\r\n") {
		colon := strings.index_byte(line, ':')
		if colon <= 0 {
			return 0, .Malformed
		}
		name := line[:colon]
		value := strings.trim_space(line[colon + 1:])

		switch {
		case strings.equal_fold(name, "Content-Length"):
			n, ok := strconv.parse_int(value, 10)
			if !ok || n < 0 || !is_all_digits(value) {
				return 0, .Malformed
			}
			if have_length && n != content_length {
				return 0, .Malformed
			}
			have_length = true
			content_length = n
		case strings.equal_fold(name, "Transfer-Encoding"):
			if !strings.equal_fold(value, "identity") {
				return 0, .Unsupported
			}
		}
	}
	return content_length, .None
}

@(private = "file")
is_all_digits :: proc(s: string) -> bool {
	if s == "" {
		return false
	}
	for c in transmute([]byte)s {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

// write_response sends a complete response and announces that the connection
// will be closed afterwards.
write_response :: proc(sock: net.TCP_Socket, res: Response) -> net.TCP_Send_Error {
	head_buf: [512]byte
	b := strings.builder_from_bytes(head_buf[:])

	fmt.sbprintf(&b, "HTTP/1.1 %d %s\r\n", u16(res.status), status_reason(res.status))
	if res.content_type != "" {
		fmt.sbprintf(&b, "Content-Type: %s\r\n", res.content_type)
	}
	if res.allow != "" {
		fmt.sbprintf(&b, "Allow: %s\r\n", res.allow)
	}
	fmt.sbprintf(&b, "Content-Length: %d\r\nConnection: close\r\n\r\n", len(res.body))

	head := strings.to_string(b)
	if len(res.body) > 0 && len(res.body) <= 4096 {
		// Coalesce small responses into one write.
		buf: [512 + 4096]byte
		n := copy(buf[:], head)
		n += copy(buf[n:], res.body)
		net.send_tcp(sock, buf[:n]) or_return
		return nil
	}
	net.send_tcp(sock, transmute([]byte)head) or_return
	if len(res.body) > 0 {
		net.send_tcp(sock, res.body) or_return
	}
	return nil
}

// kvhttp: an in-memory HTTP/1.1 key-value server.
package kvhttp

import "base:runtime"
import "core:fmt"
import "core:net"
import "core:os"
import "core:strconv"
import "core:sync/chan"
import "core:sys/posix"
import "core:thread"
import "core:time"

WORKER_COUNT :: 128
ACCEPT_QUEUE :: 1024
SOCKET_TIMEOUT :: 10 * time.Second

Server :: struct {
	store: Store,
	queue: chan.Chan(net.TCP_Socket),
}

main :: proc() {
	if len(os.args) != 2 {
		fmt.eprintfln("usage: %s <port>", os.args[0])
		os.exit(2)
	}
	port, ok := strconv.parse_int(os.args[1], 10)
	if !ok || port < 1 || port > 65535 {
		fmt.eprintfln("invalid port: %q", os.args[1])
		os.exit(2)
	}

	// Writes to a peer that already hung up must not kill the process.
	posix.signal(.SIGPIPE, auto_cast posix.SIG_IGN)

	listener, listen_err := net.listen_tcp({address = net.IP4_Loopback, port = port}, backlog = 1024)
	if listen_err != nil {
		fmt.eprintfln("listen on 127.0.0.1:%d: %v", port, listen_err)
		os.exit(1)
	}
	defer net.close(listener)

	server: Server
	store_init(&server.store)
	defer store_destroy(&server.store)

	queue_err: runtime.Allocator_Error
	server.queue, queue_err = chan.create_buffered(chan.Chan(net.TCP_Socket), ACCEPT_QUEUE, context.allocator)
	if queue_err != nil {
		fmt.eprintfln("create connection queue: %v", queue_err)
		os.exit(1)
	}
	defer chan.destroy(server.queue)

	workers: [WORKER_COUNT]^thread.Thread
	for &w in workers {
		w = thread.create_and_start_with_poly_data(&server, worker)
	}

	for {
		client, _, accept_err := net.accept_tcp(listener)
		if accept_err != nil {
			// Transient failures (EMFILE, ECONNABORTED, ...) must not stop the server.
			time.sleep(10 * time.Millisecond)
			continue
		}
		if !chan.send(server.queue, client) {
			net.close(client)
			break
		}
	}

	chan.close(server.queue)
	thread.join_multiple(..workers[:])
	for w in workers {
		thread.destroy(w)
	}
}

@(private = "file")
worker :: proc(server: ^Server) {
	for {
		client, ok := chan.recv(server.queue)
		if !ok {
			return
		}
		serve_connection(server, client)
		free_all(context.temp_allocator)
	}
}

// serve_connection handles a single request and closes the connection.
@(private = "file")
serve_connection :: proc(server: ^Server, client: net.TCP_Socket) {
	defer net.close(client)

	_ = net.set_option(client, .Receive_Timeout, SOCKET_TIMEOUT)
	_ = net.set_option(client, .Send_Timeout, SOCKET_TIMEOUT)
	_ = net.set_option(client, .TCP_Nodelay, true)

	head_buf: [MAX_HEADER_BYTES]byte
	body_allocator := server.store.allocator

	req, read_err := read_request(client, head_buf[:], body_allocator)
	switch read_err {
	case .None:
	case .Closed:
		return
	case .Malformed, .Timeout, .Too_Large, .Header_Large, .Unsupported, .Out_Of_Memory:
		_ = write_response(client, {status = read_error_status(read_err)})
		discard_input(client)
		return
	}

	res, body_consumed := handle(&server.store, req)
	if !body_consumed {
		delete(req.body, body_allocator)
	}
	_ = write_response(client, res)
}

// discard_input half-closes the socket and drains unread request bytes so the
// peer receives the error response instead of a connection reset.
@(private = "file")
discard_input :: proc(client: net.TCP_Socket) {
	_ = net.shutdown(client, .Send)
	_ = net.set_option(client, .Receive_Timeout, 1 * time.Second)

	scratch: [16 * 1024]byte
	budget := 4 * MAX_BODY_BYTES
	for budget > 0 {
		n, err := net.recv_tcp(client, scratch[:])
		if err != nil || n == 0 {
			return
		}
		budget -= n
	}
}

package kvhttp

import "core:strings"

MAX_KEY_LEN :: 64

KV_PREFIX :: "/kv/"

// handle routes a request against the store. Response bodies are allocated with
// `context.temp_allocator`. Ownership of `req.body` passes to the store on a
// successful PUT; otherwise it remains with the caller (body_consumed = false).
handle :: proc(store: ^Store, req: Request) -> (res: Response, body_consumed: bool) {
	switch {
	case req.path == "/health":
		if req.method != "GET" {
			return method_not_allowed("GET"), false
		}
		return {status = .OK, content_type = "text/plain; charset=utf-8", body = transmute([]byte)string("ok")}, false

	case req.path == "/kv":
		if req.method != "GET" {
			return method_not_allowed("GET"), false
		}
		return list_keys(store), false

	case strings.has_prefix(req.path, KV_PREFIX):
		key := req.path[len(KV_PREFIX):]
		if !is_valid_key(key) {
			return {status = .Bad_Request}, false
		}
		switch req.method {
		case "GET":
			value, found := store_get(store, key, context.temp_allocator)
			if !found {
				return {status = .Not_Found}, false
			}
			return {status = .OK, content_type = "application/octet-stream", body = value}, false
		case "PUT":
			created, err := store_put(store, key, req.body)
			if err != nil {
				return {status = .Internal_Server_Error}, true
			}
			return {status = .Created if created else .OK}, true
		case "DELETE":
			if !store_delete(store, key) {
				return {status = .Not_Found}, false
			}
			return {status = .No_Content}, false
		case:
			return method_not_allowed("GET, PUT, DELETE"), false
		}
	}
	return {status = .Not_Found}, false
}

is_valid_key :: proc(key: string) -> bool {
	if len(key) < 1 || len(key) > MAX_KEY_LEN {
		return false
	}
	for c in transmute([]byte)key {
		switch c {
		case 'A' ..= 'Z', 'a' ..= 'z', '0' ..= '9', '_', '-':
		case:
			return false
		}
	}
	return true
}

@(private = "file")
method_not_allowed :: proc(allow: string) -> Response {
	return {status = .Method_Not_Allowed, allow = allow}
}

@(private = "file")
list_keys :: proc(store: ^Store) -> Response {
	keys := store_keys(store, context.temp_allocator)

	// Keys are restricted to [A-Za-z0-9_-], so they never need JSON escaping.
	b := strings.builder_make(context.temp_allocator)
	strings.write_byte(&b, '[')
	for key, i in keys {
		if i > 0 {
			strings.write_byte(&b, ',')
		}
		strings.write_byte(&b, '"')
		strings.write_string(&b, key)
		strings.write_byte(&b, '"')
	}
	strings.write_byte(&b, ']')

	return {status = .OK, content_type = "application/json", body = b.buf[:]}
}

package kvhttp

import "base:runtime"
import "core:slice"
import "core:strings"
import "core:sync"

// Store is a thread-safe in-memory key-value map. Keys and values are owned by
// the store and live in `allocator`, which must be safe for concurrent use.
Store :: struct {
	lock:      sync.RW_Mutex,
	entries:   map[string][]byte,
	allocator: runtime.Allocator,
}

store_init :: proc(s: ^Store, allocator := context.allocator) {
	s.allocator = allocator
	s.entries = make(map[string][]byte, allocator = allocator)
}

store_destroy :: proc(s: ^Store) {
	for k, v in s.entries {
		delete(k, s.allocator)
		delete(v, s.allocator)
	}
	delete(s.entries)
	s^ = {}
}

// store_put takes ownership of `value`, which must have been allocated with the
// store's allocator, even on failure. Returns true if the key did not exist before.
store_put :: proc(s: ^Store, key: string, value: []byte) -> (created: bool, err: runtime.Allocator_Error) {
	sync.guard(&s.lock)

	key_ptr, value_ptr, just_inserted, map_err := map_entry(&s.entries, key)
	if map_err != nil {
		delete(value, s.allocator)
		return false, map_err
	}
	if just_inserted {
		owned_key, clone_err := strings.clone(key, s.allocator)
		if clone_err != nil {
			delete_key(&s.entries, key)
			delete(value, s.allocator)
			return false, clone_err
		}
		key_ptr^ = owned_key
	} else {
		delete(value_ptr^, s.allocator)
	}
	value_ptr^ = value
	return just_inserted, nil
}

// store_get returns a copy of the stored value allocated with `allocator`.
store_get :: proc(s: ^Store, key: string, allocator := context.allocator) -> (value: []byte, found: bool) {
	sync.shared_guard(&s.lock)

	stored := s.entries[key] or_return
	return slice.clone(stored, allocator), true
}

store_delete :: proc(s: ^Store, key: string) -> (deleted: bool) {
	sync.guard(&s.lock)

	if key not_in s.entries {
		return false
	}
	k, v := delete_key(&s.entries, key)
	delete(k, s.allocator)
	delete(v, s.allocator)
	return true
}

// store_keys returns every key sorted ascending; the strings are copies owned
// by the caller, allocated with `allocator`.
store_keys :: proc(s: ^Store, allocator := context.allocator) -> []string {
	keys: []string
	{
		sync.shared_guard(&s.lock)
		keys = make([]string, len(s.entries), allocator)
		i := 0
		for k in s.entries {
			keys[i] = strings.clone(k, allocator)
			i += 1
		}
	}
	slice.sort(keys)
	return keys
}
